const TIEMPOS = [{"audio": "guiones/002-sin-agua/alineacion/parte1.json", "duration": 94.04, "paragraphs": [{"start": 0.14, "end": 7.64, "text": "Imagina que despiertas... y no hay agua. Ni una gota. Ni en la llave, ni en el refri, ni en ningún lado.", "sentences": [{"text": "Imagina que despiertas...", "start": 0.14, "end": 1.58, "words": [["Imagina", 0.14, 0.54], ["que", 0.62, 0.7], ["despiertas...", 0.74, 1.58]]}, {"text": "y no hay agua.", "start": 2.14, "end": 3.08, "words": [["y", 2.14, 2.18], ["no", 2.32, 2.46], ["hay", 2.5, 2.68], ["agua.", 2.74, 3.08]]}, {"text": "Ni una gota.", "start": 3.56, "end": 4.44, "words": [["Ni", 3.56, 3.64], ["una", 3.78, 3.96], ["gota.", 4.04, 4.44]]}, {"text": "Ni en la llave, ni en el refri, ni en ningún lado.", "start": 4.88, "end": 7.64, "words": [["Ni", 4.88, 4.92], ["en", 4.96, 5.02], ["la", 5.06, 5.14], ["llave,", 5.22, 5.62], ["ni", 5.76, 5.82], ["en", 5.84, 5.9], ["el", 5.94, 6.02], ["refri,", 6.14, 6.54], ["ni", 6.72, 6.76], ["en", 6.8, 6.86], ["ningún", 6.92, 7.28], ["lado.", 7.34, 7.64]]}]}, {"start": 8.0, "end": 14.64, "text": "¿Cuánto tiempo crees que aguantarías? ¿Una semana? ¿Un mes? La respuesta es MUCHO menos de lo que crees.", "sentences": [{"text": "¿Cuánto tiempo crees que aguantarías?", "start": 8.0, "end": 9.64, "words": [["¿Cuánto", 8.0, 8.24], ["tiempo", 8.32, 8.56], ["crees", 8.66, 8.86], ["que", 8.9, 8.94], ["aguantarías?", 8.98, 9.64]]}, {"text": "¿Una semana?", "start": 9.94, "end": 10.54, "words": [["¿Una", 9.94, 10.12], ["semana?", 10.2, 10.54]]}, {"text": "¿Un mes?", "start": 10.94, "end": 11.4, "words": [["¿Un", 10.94, 11.08], ["mes?", 11.14, 11.4]]}, {"text": "La respuesta es MUCHO menos de lo que crees.", "start": 11.78, "end": 14.64, "words": [["La", 11.78, 11.84], ["respuesta", 11.92, 12.5], ["es", 12.56, 12.66], ["MUCHO", 12.94, 13.32], ["menos", 13.52, 13.86], ["de", 13.9, 13.96], ["lo", 14.0, 14.04], ["que", 14.1, 14.22], ["crees.", 14.28, 14.64]]}]}, {"start": 15.04, "end": 28.84, "text": "En 1979, un joven de dieciocho años fue encerrado en una celda en Austria... y se olvidaron de él. Pasaron dieciocho días sin comida y sin agua. Y lo que hizo para sobrevivir... es increíble.", "sentences": [{"text": "En 1979, un joven de dieciocho años fue encerrado en una celda en Austria...", "start": 15.04, "end": 20.3, "words": [["En", 15.04, 15.12], ["1979,", 15.14, 16.62], ["un", 16.84, 16.9], ["joven", 16.96, 17.18], ["de", 17.22, 17.3], ["dieciocho", 17.34, 17.92], ["años", 18.04, 18.34], ["fue", 18.38, 18.46], ["encerrado", 18.48, 18.9], ["en", 18.92, 18.98], ["una", 19.04, 19.16], ["celda", 19.3, 19.58], ["en", 19.6, 19.7], ["Austria...", 19.78, 20.3]]}, {"text": "y se olvidaron de él.", "start": 20.94, "end": 22.14, "words": [["y", 20.94, 20.98], ["se", 21.06, 21.1], ["olvidaron", 21.16, 21.72], ["de", 21.78, 21.88], ["él.", 21.98, 22.14]]}, {"text": "Pasaron dieciocho días sin comida y sin agua.", "start": 22.44, "end": 25.56, "words": [["Pasaron", 22.44, 22.84], ["dieciocho", 22.9, 23.58], ["días", 23.64, 23.92], ["sin", 23.98, 24.14], ["comida", 24.2, 24.8], ["y", 24.84, 24.92], ["sin", 25.0, 25.16], ["agua.", 25.28, 25.56]]}, {"text": "Y lo que hizo para sobrevivir...", "start": 25.9, "end": 27.48, "words": [["Y", 25.9, 25.94], ["lo", 25.98, 26.08], ["que", 26.12, 26.22], ["hizo", 26.3, 26.52], ["para", 26.56, 26.74], ["sobrevivir...", 26.8, 27.48]]}, {"text": "es increíble.", "start": 27.92, "end": 28.84, "words": [["es", 27.92, 28.06], ["increíble.", 28.14, 28.84]]}]}, {"start": 29.26, "end": 39.18, "text": "Hoy vamos a ver, hora por hora, qué le pasa a tu cuerpo cuando dejas de tomar agua. Y al final te voy a contar por qué tomar DEMASIADA agua también puede ser peligroso.", "sentences": [{"text": "Hoy vamos a ver, hora por hora, qué le pasa a tu cuerpo cuando dejas de tomar agua.", "start": 29.26, "end": 33.86, "words": [["Hoy", 29.26, 29.4], ["vamos", 29.44, 29.68], ["a", 29.72, 29.78], ["ver,", 29.82, 29.98], ["hora", 30.16, 30.46], ["por", 30.52, 30.64], ["hora,", 30.7, 30.9], ["qué", 31.1, 31.18], ["le", 31.22, 31.34], ["pasa", 31.38, 31.6], ["a", 31.64, 31.68], ["tu", 31.74, 31.84], ["cuerpo", 31.9, 32.28], ["cuando", 32.34, 32.64], ["dejas", 32.72, 33.04], ["de", 33.06, 33.16], ["tomar", 33.2, 33.5], ["agua.", 33.6, 33.86]]}, {"text": "Y al final te voy a contar por qué tomar DEMASIADA agua también puede ser peligroso.", "start": 34.16, "end": 39.18, "words": [["Y", 34.16, 34.18], ["al", 34.22, 34.3], ["final", 34.34, 34.62], ["te", 34.66, 34.72], ["voy", 34.76, 34.86], ["a", 34.9, 34.96], ["contar", 35.0, 35.38], ["por", 35.42, 35.6], ["qué", 35.64, 35.76], ["tomar", 35.82, 36.12], ["DEMASIADA", 36.18, 37.0], ["agua", 37.14, 37.56], ["también", 37.62, 38.06], ["puede", 38.1, 38.32], ["ser", 38.38, 38.54], ["peligroso.", 38.58, 39.18]]}]}, {"start": 39.46, "end": 51.5, "text": "Primero, algo que tal vez no sabías: tu cuerpo es, más o menos, sesenta por ciento agua. Si pesas setenta kilos, unos cuarenta son puro líquido. ¡Eres prácticamente una botella con patas!", "sentences": [{"text": "Primero, algo que tal vez no sabías: tu cuerpo es, más o menos, sesenta por ciento agua.", "start": 39.46, "end": 45.28, "words": [["Primero,", 39.46, 39.82], ["algo", 40.1, 40.32], ["que", 40.34, 40.52], ["tal", 40.58, 40.78], ["vez", 40.82, 41.02], ["no", 41.06, 41.16], ["sabías:", 41.22, 41.66], ["tu", 41.96, 42.04], ["cuerpo", 42.1, 42.42], ["es,", 42.5, 42.66], ["más", 42.9, 43.06], ["o", 43.1, 43.18], ["menos,", 43.24, 43.56], ["sesenta", 43.76, 44.34], ["por", 44.4, 44.54], ["ciento", 44.6, 44.92], ["agua.", 45.04, 45.28]]}, {"text": "Si pesas setenta kilos, unos cuarenta son puro líquido.", "start": 45.58, "end": 49.08, "words": [["Si", 45.58, 45.7], ["pesas", 45.74, 46.02], ["setenta", 46.08, 46.56], ["kilos,", 46.62, 46.98], ["unos", 47.18, 47.36], ["cuarenta", 47.42, 47.92], ["son", 48.0, 48.3], ["puro", 48.36, 48.6], ["líquido.", 48.66, 49.08]]}, {"text": "¡Eres prácticamente una botella con patas!", "start": 49.28, "end": 51.5, "words": [["¡Eres", 49.28, 49.58], ["prácticamente", 49.62, 50.24], ["una", 50.28, 50.4], ["botella", 50.42, 50.8], ["con", 50.84, 51.02], ["patas!", 51.06, 51.5]]}]}, {"start": 51.84, "end": 64.14, "text": "Y no está repartida igual. Tu sangre es casi toda agua. Tu cerebro y tu corazón, alrededor de tres cuartas partes. Y hasta tus huesos, que parecen secos, tienen cerca de una tercera parte de agua.", "sentences": [{"text": "Y no está repartida igual.", "start": 51.84, "end": 53.42, "words": [["Y", 51.84, 51.9], ["no", 51.98, 52.1], ["está", 52.18, 52.42], ["repartida", 52.48, 53.02], ["igual.", 53.06, 53.42]]}, {"text": "Tu sangre es casi toda agua.", "start": 53.64, "end": 55.74, "words": [["Tu", 53.64, 53.76], ["sangre", 53.86, 54.32], ["es", 54.4, 54.54], ["casi", 54.6, 54.98], ["toda", 55.04, 55.34], ["agua.", 55.44, 55.74]]}, {"text": "Tu cerebro y tu corazón, alrededor de tres cuartas partes.", "start": 56.0, "end": 59.34, "words": [["Tu", 56.0, 56.1], ["cerebro", 56.14, 56.5], ["y", 56.52, 56.56], ["tu", 56.6, 56.68], ["corazón,", 56.72, 57.2], ["alrededor", 57.4, 57.88], ["de", 57.92, 58.1], ["tres", 58.14, 58.4], ["cuartas", 58.44, 58.84], ["partes.", 58.9, 59.34]]}, {"text": "Y hasta tus huesos, que parecen secos, tienen cerca de una tercera parte de agua.", "start": 59.6, "end": 64.14, "words": [["Y", 59.6, 59.64], ["hasta", 59.68, 59.9], ["tus", 59.94, 60.08], ["huesos,", 60.12, 60.54], ["que", 60.68, 60.78], ["parecen", 60.82, 61.2], ["secos,", 61.26, 61.64], ["tienen", 61.82, 62.04], ["cerca", 62.1, 62.38], ["de", 62.42, 62.5], ["una", 62.58, 62.76], ["tercera", 62.8, 63.34], ["parte", 63.38, 63.66], ["de", 63.72, 63.8], ["agua.", 63.9, 64.14]]}]}, {"start": 64.48, "end": 77.04, "text": "Y esa agua no se queda quieta. Todos los días pierdes entre dos y tres litros: cuando vas al baño, cuando sudas... y hasta cuando respiras. Sí, cada vez que exhalas, sale un poquito de vapor de agua.", "sentences": [{"text": "Y esa agua no se queda quieta.", "start": 64.48, "end": 66.34, "words": [["Y", 64.48, 64.52], ["esa", 64.58, 64.8], ["agua", 64.9, 65.16], ["no", 65.32, 65.48], ["se", 65.54, 65.64], ["queda", 65.68, 65.92], ["quieta.", 65.98, 66.34]]}, {"text": "Todos los días pierdes entre dos y tres litros: cuando vas al baño, cuando sudas...", "start": 66.6, "end": 71.66, "words": [["Todos", 66.6, 66.88], ["los", 66.92, 67.08], ["días", 67.12, 67.48], ["pierdes", 67.54, 67.84], ["entre", 67.9, 68.2], ["dos", 68.26, 68.54], ["y", 68.6, 68.72], ["tres", 68.76, 69.0], ["litros:", 69.06, 69.46], ["cuando", 69.68, 69.9], ["vas", 69.94, 70.08], ["al", 70.12, 70.22], ["baño,", 70.28, 70.66], ["cuando", 70.84, 71.12], ["sudas...", 71.22, 71.66]]}, {"text": "y hasta cuando respiras.", "start": 71.94, "end": 73.2, "words": [["y", 71.94, 71.96], ["hasta", 72.0, 72.24], ["cuando", 72.28, 72.52], ["respiras.", 72.58, 73.2]]}, {"text": "Sí, cada vez que exhalas, sale un poquito de vapor de agua.", "start": 73.54, "end": 77.04, "words": [["Sí,", 73.54, 73.68], ["cada", 74.0, 74.22], ["vez", 74.26, 74.4], ["que", 74.44, 74.48], ["exhalas,", 74.52, 74.98], ["sale", 75.16, 75.34], ["un", 75.38, 75.5], ["poquito", 75.54, 76.02], ["de", 76.06, 76.14], ["vapor", 76.18, 76.5], ["de", 76.54, 76.62], ["agua.", 76.72, 77.04]]}]}, {"start": 77.22, "end": 88.3, "text": "¿Y para qué tanta agua? Para casi todo. El agua lleva los nutrientes a tus células, saca los desechos, protege tu cerebro como un cojín... y funciona como el aire acondicionado de tu cuerpo.", "sentences": [{"text": "¿Y para qué tanta agua?", "start": 77.22, "end": 78.52, "words": [["¿Y", 77.22, 77.4], ["para", 77.44, 77.7], ["qué", 77.74, 77.88], ["tanta", 77.94, 78.24], ["agua?", 78.34, 78.52]]}, {"text": "Para casi todo.", "start": 78.9, "end": 79.84, "words": [["Para", 78.9, 79.12], ["casi", 79.18, 79.5], ["todo.", 79.56, 79.84]]}, {"text": "El agua lleva los nutrientes a tus células, saca los desechos, protege tu cerebro como un cojín...", "start": 80.18, "end": 85.54, "words": [["El", 80.18, 80.26], ["agua", 80.34, 80.56], ["lleva", 80.58, 80.8], ["los", 80.84, 80.96], ["nutrientes", 81.0, 81.48], ["a", 81.54, 81.58], ["tus", 81.62, 81.74], ["células,", 81.82, 82.34], ["saca", 82.54, 82.74], ["los", 82.78, 82.9], ["desechos,", 82.94, 83.56], ["protege", 83.7, 84.08], ["tu", 84.12, 84.22], ["cerebro", 84.28, 84.74], ["como", 84.78, 84.98], ["un", 85.02, 85.1], ["cojín...", 85.14, 85.54]]}, {"text": "y funciona como el aire acondicionado de tu cuerpo.", "start": 85.78, "end": 88.3, "words": [["y", 85.78, 85.84], ["funciona", 85.88, 86.32], ["como", 86.36, 86.5], ["el", 86.54, 86.64], ["aire", 86.7, 86.84], ["acondicionado", 86.9, 87.64], ["de", 87.68, 87.76], ["tu", 87.8, 87.92], ["cuerpo.", 87.96, 88.3]]}]}, {"start": 88.64, "end": 93.74, "text": "Así que si dejas de tomar agua, tu cuerpo empieza a gastar sus reservas desde el primer minuto.", "sentences": [{"text": "Así que si dejas de tomar agua, tu cuerpo empieza a gastar sus reservas desde el primer minuto.", "start": 88.64, "end": 93.74, "words": [["Así", 88.64, 88.8], ["que", 88.84, 88.94], ["si", 89.0, 89.1], ["dejas", 89.14, 89.4], ["de", 89.44, 89.52], ["tomar", 89.56, 89.82], ["agua,", 89.92, 90.14], ["tu", 90.34, 90.44], ["cuerpo", 90.48, 90.7], ["empieza", 90.74, 91.1], ["a", 91.14, 91.18], ["gastar", 91.22, 91.56], ["sus", 91.6, 91.76], ["reservas", 91.8, 92.3], ["desde", 92.36, 92.58], ["el", 92.6, 92.74], ["primer", 92.76, 93.2], ["minuto.", 93.26, 93.74]]}]}]}, {"audio": "guiones/002-sin-agua/alineacion/parte2.json", "duration": 101.62, "paragraphs": [{"start": 0.1, "end": 4.42, "text": "Pasan las primeras horas. Nada grave... hasta que aparece la sed.", "sentences": [{"text": "Pasan las primeras horas.", "start": 0.1, "end": 1.36, "words": [["Pasan", 0.1, 0.36], ["las", 0.4, 0.52], ["primeras", 0.56, 0.94], ["horas.", 0.96, 1.36]]}, {"text": "Nada grave...", "start": 1.74, "end": 2.38, "words": [["Nada", 1.74, 1.96], ["grave...", 2.0, 2.38]]}, {"text": "hasta que aparece la sed.", "start": 2.76, "end": 4.42, "words": [["hasta", 2.76, 3.18], ["que", 3.22, 3.3], ["aparece", 3.36, 3.88], ["la", 3.92, 4.04], ["sed.", 4.12, 4.42]]}]}, {"start": 4.74, "end": 15.42, "text": "Y aquí viene algo curioso: cuando sientes sed, tu cuerpo ya perdió entre uno y dos por ciento de su agua. O sea, ¡la sed llega tarde! Es una alarma que suena cuando ya empezó el problema.", "sentences": [{"text": "Y aquí viene algo curioso: cuando sientes sed, tu cuerpo ya perdió entre uno y dos por ciento de su agua.", "start": 4.74, "end": 10.68, "words": [["Y", 4.74, 4.78], ["aquí", 4.84, 5.0], ["viene", 5.04, 5.24], ["algo", 5.3, 5.5], ["curioso:", 5.54, 6.0], ["cuando", 6.22, 6.46], ["sientes", 6.52, 6.86], ["sed,", 6.92, 7.16], ["tu", 7.34, 7.42], ["cuerpo", 7.46, 7.72], ["ya", 7.76, 7.86], ["perdió", 7.9, 8.2], ["entre", 8.24, 8.58], ["uno", 8.72, 9.0], ["y", 9.06, 9.16], ["dos", 9.22, 9.4], ["por", 9.5, 9.66], ["ciento", 9.72, 10.02], ["de", 10.06, 10.16], ["su", 10.22, 10.32], ["agua.", 10.42, 10.68]]}, {"text": "O sea, ¡la sed llega tarde!", "start": 10.9, "end": 12.72, "words": [["O", 10.9, 10.94], ["sea,", 11.04, 11.26], ["¡la", 11.42, 11.64], ["sed", 11.78, 11.92], ["llega", 11.98, 12.2], ["tarde!", 12.36, 12.72]]}, {"text": "Es una alarma que suena cuando ya empezó el problema.", "start": 13.0, "end": 15.42, "words": [["Es", 13.0, 13.08], ["una", 13.14, 13.24], ["alarma", 13.28, 13.56], ["que", 13.64, 13.74], ["suena", 13.78, 14.02], ["cuando", 14.06, 14.3], ["ya", 14.42, 14.52], ["empezó", 14.54, 14.84], ["el", 14.86, 14.94], ["problema.", 14.98, 15.42]]}]}, {"start": 15.7, "end": 22.22, "text": "Con solo dos por ciento menos de agua, ya te cuesta más concentrarte, te cansas más rápido y tu humor empeora.", "sentences": [{"text": "Con solo dos por ciento menos de agua, ya te cuesta más concentrarte, te cansas más rápido y tu humor empeora.", "start": 15.7, "end": 22.22, "words": [["Con", 15.7, 15.8], ["solo", 15.88, 16.08], ["dos", 16.22, 16.4], ["por", 16.5, 16.64], ["ciento", 16.7, 16.98], ["menos", 17.1, 17.38], ["de", 17.42, 17.5], ["agua,", 17.6, 17.86], ["ya", 18.02, 18.08], ["te", 18.14, 18.22], ["cuesta", 18.26, 18.54], ["más", 18.64, 18.82], ["concentrarte,", 18.86, 19.58], ["te", 19.78, 19.86], ["cansas", 19.92, 20.24], ["más", 20.3, 20.48], ["rápido", 20.56, 21.1], ["y", 21.16, 21.18], ["tu", 21.28, 21.36], ["humor", 21.4, 21.7], ["empeora.", 21.74, 22.22]]}]}, {"start": 22.5, "end": 34.32, "text": "Hora doce. Tu boca empieza a sentirse pastosa... y aparece el mal aliento. ¿Por qué? Porque hay menos saliva, y la saliva es la que limpia tu boca. Sin ella, las bacterias hacen fiesta.", "sentences": [{"text": "Hora doce.", "start": 22.5, "end": 23.3, "words": [["Hora", 22.5, 22.74], ["doce.", 22.9, 23.3]]}, {"text": "Tu boca empieza a sentirse pastosa...", "start": 23.54, "end": 25.58, "words": [["Tu", 23.54, 23.62], ["boca", 23.66, 23.84], ["empieza", 23.88, 24.24], ["a", 24.26, 24.3], ["sentirse", 24.36, 24.88], ["pastosa...", 24.92, 25.58]]}, {"text": "y aparece el mal aliento.", "start": 25.9, "end": 27.46, "words": [["y", 25.9, 25.92], ["aparece", 26.0, 26.5], ["el", 26.52, 26.6], ["mal", 26.74, 26.9], ["aliento.", 26.96, 27.46]]}, {"text": "¿Por qué?", "start": 27.74, "end": 28.04, "words": [["¿Por", 27.74, 27.86], ["qué?", 27.94, 28.04]]}, {"text": "Porque hay menos saliva, y la saliva es la que limpia tu boca.", "start": 28.32, "end": 31.58, "words": [["Porque", 28.32, 28.52], ["hay", 28.54, 28.66], ["menos", 28.74, 29.0], ["saliva,", 29.04, 29.44], ["y", 29.66, 29.72], ["la", 29.76, 29.8], ["saliva", 29.86, 30.24], ["es", 30.28, 30.38], ["la", 30.42, 30.48], ["que", 30.56, 30.66], ["limpia", 30.74, 31.04], ["tu", 31.12, 31.2], ["boca.", 31.26, 31.58]]}, {"text": "Sin ella, las bacterias hacen fiesta.", "start": 31.86, "end": 34.32, "words": [["Sin", 31.86, 32.0], ["ella,", 32.1, 32.28], ["las", 32.56, 32.7], ["bacterias", 32.74, 33.36], ["hacen", 33.4, 33.78], ["fiesta.", 33.9, 34.32]]}]}, {"start": 34.68, "end": 36.48, "text": "¡Llegas a las veinticuatro horas!", "sentences": [{"text": "¡Llegas a las veinticuatro horas!", "start": 34.68, "end": 36.48, "words": [["¡Llegas", 34.68, 35.02], ["a", 35.06, 35.1], ["las", 35.14, 35.24], ["veinticuatro", 35.3, 36.04], ["horas!", 36.08, 36.48]]}]}, {"start": 36.74, "end": 46.72, "text": "Tu cerebro manda una señal de emergencia: una hormona que les dice a los riñones \"¡no tiren el agua!\". Por eso orinas mucho menos... y la orina se pone oscura, casi del color del té.", "sentences": [{"text": "Tu cerebro manda una señal de emergencia: una hormona que les dice a los riñones \"¡no tiren el agua!\".", "start": 36.74, "end": 42.02, "words": [["Tu", 36.74, 36.8], ["cerebro", 36.86, 37.16], ["manda", 37.24, 37.46], ["una", 37.5, 37.6], ["señal", 37.7, 38.06], ["de", 38.12, 38.16], ["emergencia:", 38.18, 38.78], ["una", 39.06, 39.18], ["hormona", 39.2, 39.58], ["que", 39.68, 39.74], ["les", 39.78, 39.9], ["dice", 39.92, 40.1], ["a", 40.12, 40.14], ["los", 40.18, 40.28], ["riñones", 40.34, 40.74], ["\"¡no", 40.9, 41.06], ["tiren", 41.26, 41.54], ["el", 41.58, 41.68], ["agua!\".", 41.76, 42.02]]}, {"text": "Por eso orinas mucho menos...", "start": 42.28, "end": 43.8, "words": [["Por", 42.28, 42.38], ["eso", 42.44, 42.66], ["orinas", 42.74, 43.06], ["mucho", 43.14, 43.34], ["menos...", 43.44, 43.8]]}, {"text": "y la orina se pone oscura, casi del color del té.", "start": 44.02, "end": 46.72, "words": [["y", 44.02, 44.04], ["la", 44.1, 44.14], ["orina", 44.18, 44.44], ["se", 44.52, 44.64], ["pone", 44.68, 44.82], ["oscura,", 44.86, 45.3], ["casi", 45.54, 45.82], ["del", 45.86, 45.96], ["color", 46.04, 46.3], ["del", 46.36, 46.48], ["té.", 46.58, 46.72]]}]}, {"start": 47.02, "end": 56.24, "text": "Tu boca se seca. Tu piel pierde elasticidad. Si te pellizcas la mano, la piel tarda en regresar a su lugar. Y aparece un dolor de cabeza que no se quita.", "sentences": [{"text": "Tu boca se seca.", "start": 47.02, "end": 48.14, "words": [["Tu", 47.02, 47.08], ["boca", 47.18, 47.46], ["se", 47.56, 47.64], ["seca.", 47.8, 48.14]]}, {"text": "Tu piel pierde elasticidad.", "start": 48.42, "end": 49.98, "words": [["Tu", 48.42, 48.48], ["piel", 48.6, 48.8], ["pierde", 48.98, 49.28], ["elasticidad.", 49.3, 49.98]]}, {"text": "Si te pellizcas la mano, la piel tarda en regresar a su lugar.", "start": 50.26, "end": 53.36, "words": [["Si", 50.26, 50.32], ["te", 50.38, 50.48], ["pellizcas", 50.5, 50.92], ["la", 50.96, 51.02], ["mano,", 51.08, 51.34], ["la", 51.52, 51.58], ["piel", 51.68, 51.86], ["tarda", 52.04, 52.3], ["en", 52.32, 52.4], ["regresar", 52.46, 52.84], ["a", 52.86, 52.9], ["su", 52.96, 53.04], ["lugar.", 53.08, 53.36]]}, {"text": "Y aparece un dolor de cabeza que no se quita.", "start": 53.68, "end": 56.24, "words": [["Y", 53.68, 53.72], ["aparece", 53.78, 54.14], ["un", 54.16, 54.22], ["dolor", 54.26, 54.52], ["de", 54.56, 54.66], ["cabeza", 54.7, 55.06], ["que", 55.2, 55.32], ["no", 55.48, 55.6], ["se", 55.72, 55.88], ["quita.", 55.92, 56.24]]}]}, {"start": 56.58, "end": 65.58, "text": "¿Y por qué duele la cabeza? Algunos estudios han visto que, con deshidratación, el cerebro pierde un poquito de volumen. Literalmente, se encoge un poco.", "sentences": [{"text": "¿Y por qué duele la cabeza?", "start": 56.58, "end": 57.86, "words": [["¿Y", 56.58, 56.68], ["por", 56.8, 56.94], ["qué", 56.96, 57.08], ["duele", 57.1, 57.34], ["la", 57.36, 57.42], ["cabeza?", 57.5, 57.86]]}, {"text": "Algunos estudios han visto que, con deshidratación, el cerebro pierde un poquito de volumen.", "start": 58.2, "end": 63.34, "words": [["Algunos", 58.2, 58.52], ["estudios", 58.58, 59.04], ["han", 59.08, 59.18], ["visto", 59.22, 59.46], ["que,", 59.56, 59.68], ["con", 59.84, 59.96], ["deshidratación,", 60.0, 60.78], ["el", 61.0, 61.06], ["cerebro", 61.12, 61.4], ["pierde", 61.52, 61.88], ["un", 61.94, 62.14], ["poquito", 62.18, 62.7], ["de", 62.74, 62.8], ["volumen.", 62.86, 63.34]]}, {"text": "Literalmente, se encoge un poco.", "start": 63.58, "end": 65.58, "words": [["Literalmente,", 63.58, 64.4], ["se", 64.56, 64.62], ["encoge", 64.66, 65.12], ["un", 65.16, 65.26], ["poco.", 65.3, 65.58]]}]}, {"start": 65.9, "end": 67.3, "text": "¡Treinta y seis horas!", "sentences": [{"text": "¡Treinta y seis horas!", "start": 65.9, "end": 67.3, "words": [["¡Treinta", 65.9, 66.28], ["y", 66.34, 66.38], ["seis", 66.54, 66.82], ["horas!", 66.86, 67.3]]}]}, {"start": 67.66, "end": 78.14, "text": "Ahora el problema está en la sangre. Al haber menos agua, la sangre se vuelve más espesa, como si fuera jarabe. Y tu corazón tiene que latir más rápido para empujarla por todo el cuerpo.", "sentences": [{"text": "Ahora el problema está en la sangre.", "start": 67.66, "end": 69.38, "words": [["Ahora", 67.66, 67.84], ["el", 67.88, 67.92], ["problema", 68.0, 68.38], ["está", 68.44, 68.66], ["en", 68.7, 68.76], ["la", 68.8, 68.86], ["sangre.", 69.0, 69.38]]}, {"text": "Al haber menos agua, la sangre se vuelve más espesa, como si fuera jarabe.", "start": 69.68, "end": 73.74, "words": [["Al", 69.68, 69.74], ["haber", 69.76, 70.0], ["menos", 70.06, 70.34], ["agua,", 70.44, 70.66], ["la", 70.82, 70.88], ["sangre", 70.96, 71.18], ["se", 71.24, 71.32], ["vuelve", 71.36, 71.66], ["más", 71.78, 71.96], ["espesa,", 72.02, 72.54], ["como", 72.74, 72.88], ["si", 72.94, 73.04], ["fuera", 73.08, 73.28], ["jarabe.", 73.34, 73.74]]}, {"text": "Y tu corazón tiene que latir más rápido para empujarla por todo el cuerpo.", "start": 74.0, "end": 78.14, "words": [["Y", 74.0, 74.02], ["tu", 74.08, 74.18], ["corazón", 74.2, 74.64], ["tiene", 74.7, 74.9], ["que", 74.92, 75.0], ["latir", 75.04, 75.3], ["más", 75.48, 75.72], ["rápido", 75.82, 76.26], ["para", 76.28, 76.38], ["empujarla", 76.42, 76.96], ["por", 77.08, 77.2], ["todo", 77.38, 77.58], ["el", 77.62, 77.68], ["cuerpo.", 77.78, 78.14]]}]}, {"start": 78.42, "end": 83.48, "text": "Te mareas al levantarte. Sientes el pulso acelerado. Y estás agotado.", "sentences": [{"text": "Te mareas al levantarte.", "start": 78.42, "end": 79.74, "words": [["Te", 78.42, 78.5], ["mareas", 78.56, 78.96], ["al", 79.0, 79.06], ["levantarte.", 79.1, 79.74]]}, {"text": "Sientes el pulso acelerado.", "start": 80.12, "end": 81.48, "words": [["Sientes", 80.12, 80.4], ["el", 80.46, 80.6], ["pulso", 80.64, 80.86], ["acelerado.", 80.9, 81.48]]}, {"text": "Y estás agotado.", "start": 82.32, "end": 83.48, "words": [["Y", 82.32, 82.38], ["estás", 82.42, 82.84], ["agotado.", 82.92, 83.48]]}]}, {"start": 83.86, "end": 101.32, "text": "Y entonces tu cuerpo toma una decisión difícil. Empieza a mandar la poca agua que queda a lo más importante: el cerebro y el corazón. La piel, los músculos y el estómago reciben menos. Por eso las manos y los pies pueden sentirse fríos... aunque por dentro estés ardiendo.", "sentences": [{"text": "Y entonces tu cuerpo toma una decisión difícil.", "start": 83.86, "end": 86.76, "words": [["Y", 83.86, 83.9], ["entonces", 83.94, 84.52], ["tu", 84.56, 84.66], ["cuerpo", 84.7, 85.0], ["toma", 85.14, 85.36], ["una", 85.42, 85.56], ["decisión", 85.6, 86.16], ["difícil.", 86.2, 86.76]]}, {"text": "Empieza a mandar la poca agua que queda a lo más importante: el cerebro y el corazón.", "start": 87.08, "end": 92.72, "words": [["Empieza", 87.08, 87.44], ["a", 87.48, 87.52], ["mandar", 87.56, 87.92], ["la", 87.98, 88.04], ["poca", 88.22, 88.54], ["agua", 88.62, 88.82], ["que", 88.86, 88.98], ["queda", 89.02, 89.44], ["a", 89.5, 89.54], ["lo", 89.6, 89.72], ["más", 89.88, 90.06], ["importante:", 90.14, 90.78], ["el", 91.14, 91.24], ["cerebro", 91.3, 91.96], ["y", 92.0, 92.04], ["el", 92.08, 92.16], ["corazón.", 92.2, 92.72]]}, {"text": "La piel, los músculos y el estómago reciben menos.", "start": 93.06, "end": 96.1, "words": [["La", 93.06, 93.12], ["piel,", 93.26, 93.58], ["los", 93.78, 93.96], ["músculos", 94.02, 94.48], ["y", 94.5, 94.52], ["el", 94.56, 94.6], ["estómago", 94.66, 95.18], ["reciben", 95.22, 95.64], ["menos.", 95.7, 96.1]]}, {"text": "Por eso las manos y los pies pueden sentirse fríos...", "start": 96.34, "end": 99.06, "words": [["Por", 96.34, 96.44], ["eso", 96.5, 96.7], ["las", 96.74, 96.9], ["manos", 96.94, 97.18], ["y", 97.22, 97.26], ["los", 97.3, 97.46], ["pies", 97.52, 97.78], ["pueden", 97.82, 98.06], ["sentirse", 98.1, 98.58], ["fríos...", 98.66, 99.06]]}, {"text": "aunque por dentro estés ardiendo.", "start": 99.32, "end": 101.32, "words": [["aunque", 99.32, 99.6], ["por", 99.64, 99.8], ["dentro", 99.86, 100.2], ["estés", 100.26, 100.58], ["ardiendo.", 100.66, 101.32]]}]}]}, {"audio": "guiones/002-sin-agua/alineacion/parte3.json", "duration": 113.24, "paragraphs": [{"start": 0.12, "end": 6.04, "text": "Llegamos al día dos... y aquí tu cuerpo enfrenta un problema enorme: el calor.", "sentences": [{"text": "Llegamos al día dos...", "start": 0.12, "end": 1.84, "words": [["Llegamos", 0.12, 0.68], ["al", 0.76, 0.88], ["día", 0.98, 1.26], ["dos...", 1.36, 1.84]]}, {"text": "y aquí tu cuerpo enfrenta un problema enorme: el calor.", "start": 2.24, "end": 6.04, "words": [["y", 2.24, 2.26], ["aquí", 2.32, 2.54], ["tu", 2.6, 2.66], ["cuerpo", 2.76, 3.06], ["enfrenta", 3.1, 3.54], ["un", 3.58, 3.7], ["problema", 3.74, 4.18], ["enorme:", 4.24, 4.82], ["el", 5.38, 5.46], ["calor.", 5.58, 6.04]]}]}, {"start": 6.46, "end": 12.98, "text": "Normalmente, cuando tienes calor, sudas, y el sudor te enfría. Pero sin agua... ya casi no puedes sudar.", "sentences": [{"text": "Normalmente, cuando tienes calor, sudas, y el sudor te enfría.", "start": 6.46, "end": 10.1, "words": [["Normalmente,", 6.46, 7.04], ["cuando", 7.18, 7.42], ["tienes", 7.44, 7.68], ["calor,", 7.72, 8.02], ["sudas,", 8.32, 8.72], ["y", 8.96, 9.0], ["el", 9.04, 9.1], ["sudor", 9.18, 9.46], ["te", 9.54, 9.6], ["enfría.", 9.64, 10.1]]}, {"text": "Pero sin agua...", "start": 10.4, "end": 11.12, "words": [["Pero", 10.4, 10.58], ["sin", 10.62, 10.76], ["agua...", 10.84, 11.12]]}, {"text": "ya casi no puedes sudar.", "start": 11.52, "end": 12.98, "words": [["ya", 11.52, 11.6], ["casi", 11.7, 11.96], ["no", 12.02, 12.08], ["puedes", 12.24, 12.56], ["sudar.", 12.62, 12.98]]}]}, {"start": 13.26, "end": 25.7, "text": "Tu temperatura empieza a subir, y subir. ¡Y si estás en un lugar caliente, todo esto pasa muchísimo más rápido! En un desierto, bajo el sol, una persona puede perder más de un litro de sudor por hora.", "sentences": [{"text": "Tu temperatura empieza a subir, y subir.", "start": 13.26, "end": 15.9, "words": [["Tu", 13.26, 13.34], ["temperatura", 13.4, 13.9], ["empieza", 13.94, 14.34], ["a", 14.36, 14.4], ["subir,", 14.5, 14.96], ["y", 15.26, 15.3], ["subir.", 15.42, 15.9]]}, {"text": "¡Y si estás en un lugar caliente, todo esto pasa muchísimo más rápido!", "start": 16.18, "end": 20.22, "words": [["¡Y", 16.18, 16.26], ["si", 16.3, 16.36], ["estás", 16.4, 16.62], ["en", 16.68, 16.74], ["un", 16.78, 16.82], ["lugar", 16.86, 17.08], ["caliente,", 17.16, 17.64], ["todo", 17.88, 18.14], ["esto", 18.22, 18.46], ["pasa", 18.52, 18.76], ["muchísimo", 18.82, 19.5], ["más", 19.54, 19.72], ["rápido!", 19.8, 20.22]]}, {"text": "En un desierto, bajo el sol, una persona puede perder más de un litro de sudor por hora.", "start": 20.54, "end": 25.7, "words": [["En", 20.54, 20.6], ["un", 20.64, 20.7], ["desierto,", 20.74, 21.28], ["bajo", 21.48, 21.66], ["el", 21.7, 21.8], ["sol,", 21.86, 22.08], ["una", 22.36, 22.5], ["persona", 22.54, 22.92], ["puede", 22.96, 23.18], ["perder", 23.24, 23.58], ["más", 23.7, 23.9], ["de", 23.94, 24.02], ["un", 24.06, 24.16], ["litro", 24.24, 24.58], ["de", 24.62, 24.68], ["sudor", 24.78, 25.18], ["por", 25.24, 25.38], ["hora.", 25.46, 25.7]]}]}, {"start": 26.02, "end": 37.04, "text": "Cuando pierdes cerca de diez por ciento del agua de tu cuerpo, empieza lo más peligroso: confusión... alucinaciones... y tu cuerpo ya no puede controlar su temperatura.", "sentences": [{"text": "Cuando pierdes cerca de diez por ciento del agua de tu cuerpo, empieza lo más peligroso: confusión...", "start": 26.02, "end": 32.44, "words": [["Cuando", 26.02, 26.26], ["pierdes", 26.3, 26.62], ["cerca", 26.68, 27.0], ["de", 27.04, 27.16], ["diez", 27.22, 27.5], ["por", 27.54, 27.7], ["ciento", 27.76, 28.06], ["del", 28.12, 28.24], ["agua", 28.32, 28.48], ["de", 28.52, 28.6], ["tu", 28.64, 28.74], ["cuerpo,", 28.78, 29.14], ["empieza", 29.44, 29.94], ["lo", 30.02, 30.14], ["más", 30.26, 30.52], ["peligroso:", 30.56, 31.14], ["confusión...", 31.58, 32.44]]}, {"text": "alucinaciones...", "start": 32.96, "end": 34.02, "words": [["alucinaciones...", 32.96, 34.02]]}, {"text": "y tu cuerpo ya no puede controlar su temperatura.", "start": 34.34, "end": 37.04, "words": [["y", 34.34, 34.38], ["tu", 34.44, 34.54], ["cuerpo", 34.6, 34.94], ["ya", 35.06, 35.16], ["no", 35.2, 35.4], ["puede", 35.44, 35.76], ["controlar", 35.8, 36.24], ["su", 36.28, 36.38], ["temperatura.", 36.42, 37.04]]}]}, {"start": 37.42, "end": 44.7, "text": "Los riñones, que llevan días trabajando sin descanso, empiezan a fallar. Y sin ellos, los desechos se acumulan en la sangre.", "sentences": [{"text": "Los riñones, que llevan días trabajando sin descanso, empiezan a fallar.", "start": 37.42, "end": 41.62, "words": [["Los", 37.42, 37.56], ["riñones,", 37.62, 38.18], ["que", 38.26, 38.34], ["llevan", 38.38, 38.68], ["días", 38.74, 39.04], ["trabajando", 39.08, 39.62], ["sin", 39.66, 39.78], ["descanso,", 39.8, 40.34], ["empiezan", 40.62, 41.04], ["a", 41.08, 41.14], ["fallar.", 41.2, 41.62]]}, {"text": "Y sin ellos, los desechos se acumulan en la sangre.", "start": 41.86, "end": 44.7, "words": [["Y", 41.86, 41.92], ["sin", 41.96, 42.1], ["ellos,", 42.18, 42.48], ["los", 42.7, 42.82], ["desechos", 42.86, 43.28], ["se", 43.34, 43.4], ["acumulan", 43.44, 43.98], ["en", 44.02, 44.1], ["la", 44.12, 44.22], ["sangre.", 44.3, 44.7]]}]}, {"start": 44.98, "end": 49.76, "text": "Y si la pérdida llega a quince o veinte por ciento... el cuerpo ya no puede más.", "sentences": [{"text": "Y si la pérdida llega a quince o veinte por ciento...", "start": 44.98, "end": 47.86, "words": [["Y", 44.98, 45.02], ["si", 45.06, 45.12], ["la", 45.16, 45.28], ["pérdida", 45.32, 45.66], ["llega", 45.7, 45.96], ["a", 46.0, 46.12], ["quince", 46.16, 46.62], ["o", 46.66, 46.76], ["veinte", 46.82, 47.14], ["por", 47.18, 47.32], ["ciento...", 47.38, 47.86]]}, {"text": "el cuerpo ya no puede más.", "start": 48.12, "end": 49.76, "words": [["el", 48.12, 48.24], ["cuerpo", 48.28, 48.66], ["ya", 48.82, 48.94], ["no", 48.98, 49.1], ["puede", 49.14, 49.38], ["más.", 49.44, 49.76]]}]}, {"start": 50.14, "end": 68.84, "text": "Entonces... ¿cuánto se puede aguantar en total? Existe una regla famosa: tres minutos sin aire, tres días sin agua y tres semanas sin comida. No es exacta, pero da una idea: en condiciones normales, la mayoría de las personas aguantaría solo unos días. Y con mucho calor... podría ser menos de dos.", "sentences": [{"text": "Entonces...", "start": 50.14, "end": 50.74, "words": [["Entonces...", 50.14, 50.74]]}, {"text": "¿cuánto se puede aguantar en total?", "start": 51.04, "end": 52.7, "words": [["¿cuánto", 51.04, 51.3], ["se", 51.38, 51.5], ["puede", 51.54, 51.7], ["aguantar", 51.74, 52.2], ["en", 52.24, 52.32], ["total?", 52.36, 52.7]]}, {"text": "Existe una regla famosa: tres minutos sin aire, tres días sin agua y tres semanas sin comida.", "start": 53.1, "end": 58.9, "words": [["Existe", 53.1, 53.48], ["una", 53.54, 53.68], ["regla", 53.76, 54.04], ["famosa:", 54.1, 54.5], ["tres", 54.86, 55.04], ["minutos", 55.12, 55.48], ["sin", 55.52, 55.64], ["aire,", 55.72, 55.92], ["tres", 56.2, 56.44], ["días", 56.5, 56.72], ["sin", 56.76, 56.88], ["agua", 56.98, 57.36], ["y", 57.42, 57.56], ["tres", 57.62, 57.8], ["semanas", 57.86, 58.3], ["sin", 58.34, 58.46], ["comida.", 58.5, 58.9]]}, {"text": "No es exacta, pero da una idea: en condiciones normales, la mayoría de las personas aguantaría solo unos días.", "start": 59.2, "end": 65.6, "words": [["No", 59.2, 59.28], ["es", 59.34, 59.42], ["exacta,", 59.48, 59.96], ["pero", 60.12, 60.36], ["da", 60.48, 60.6], ["una", 60.64, 60.74], ["idea:", 60.8, 61.06], ["en", 61.36, 61.42], ["condiciones", 61.46, 61.92], ["normales,", 61.96, 62.52], ["la", 62.68, 62.72], ["mayoría", 62.78, 63.12], ["de", 63.16, 63.22], ["las", 63.26, 63.38], ["personas", 63.42, 63.84], ["aguantaría", 63.92, 64.42], ["solo", 64.6, 64.9], ["unos", 64.96, 65.16], ["días.", 65.22, 65.6]]}, {"text": "Y con mucho calor...", "start": 65.9, "end": 66.94, "words": [["Y", 65.9, 65.98], ["con", 66.02, 66.2], ["mucho", 66.28, 66.5], ["calor...", 66.6, 66.94]]}, {"text": "podría ser menos de dos.", "start": 67.34, "end": 68.84, "words": [["podría", 67.34, 67.72], ["ser", 67.76, 67.94], ["menos", 68.06, 68.36], ["de", 68.4, 68.48], ["dos.", 68.54, 68.84]]}]}, {"start": 69.14, "end": 72.24, "text": "¿Y el chico de la celda? ¿Cómo aguantó dieciocho días?", "sentences": [{"text": "¿Y el chico de la celda?", "start": 69.14, "end": 70.12, "words": [["¿Y", 69.14, 69.2], ["el", 69.24, 69.3], ["chico", 69.36, 69.58], ["de", 69.62, 69.68], ["la", 69.72, 69.76], ["celda?", 69.84, 70.12]]}, {"text": "¿Cómo aguantó dieciocho días?", "start": 70.4, "end": 72.24, "words": [["¿Cómo", 70.4, 70.6], ["aguantó", 70.64, 71.02], ["dieciocho", 71.12, 71.74], ["días?", 71.84, 72.24]]}]}, {"start": 72.58, "end": 91.1, "text": "Se llamaba Andreas Mihavecz. Lo dejaron en una celda de una estación de policía en Austria... y los guardias se olvidaron de él. Para sobrevivir, lamía las gotitas de agua que se condensaban en las paredes. ¡Esas pocas gotas le salvaron la vida! Cuando por fin lo encontraron, estaba muy débil, pero vivo.", "sentences": [{"text": "Se llamaba Andreas Mihavecz.", "start": 72.58, "end": 74.42, "words": [["Se", 72.58, 72.66], ["llamaba", 72.68, 73.16], ["Andreas", 73.24, 73.72], ["Mihavecz.", 73.8, 74.42]]}, {"text": "Lo dejaron en una celda de una estación de policía en Austria...", "start": 74.66, "end": 77.58, "words": [["Lo", 74.66, 74.74], ["dejaron", 74.78, 75.1], ["en", 75.14, 75.22], ["una", 75.26, 75.38], ["celda", 75.48, 75.76], ["de", 75.8, 75.88], ["una", 75.92, 76.0], ["estación", 76.04, 76.42], ["de", 76.44, 76.5], ["policía", 76.58, 77.0], ["en", 77.02, 77.1], ["Austria...", 77.18, 77.58]]}, {"text": "y los guardias se olvidaron de él.", "start": 78.16, "end": 80.08, "words": [["y", 78.16, 78.2], ["los", 78.24, 78.36], ["guardias", 78.46, 78.9], ["se", 78.96, 79.02], ["olvidaron", 79.08, 79.68], ["de", 79.72, 79.84], ["él.", 79.94, 80.08]]}, {"text": "Para sobrevivir, lamía las gotitas de agua que se condensaban en las paredes.", "start": 80.4, "end": 84.72, "words": [["Para", 80.4, 80.52], ["sobrevivir,", 80.6, 81.14], ["lamía", 81.46, 81.76], ["las", 81.8, 81.94], ["gotitas", 82.0, 82.54], ["de", 82.58, 82.66], ["agua", 82.76, 82.94], ["que", 83.0, 83.08], ["se", 83.12, 83.22], ["condensaban", 83.26, 83.92], ["en", 83.94, 84.0], ["las", 84.04, 84.14], ["paredes.", 84.22, 84.72]]}, {"text": "¡Esas pocas gotas le salvaron la vida!", "start": 84.96, "end": 87.32, "words": [["¡Esas", 84.96, 85.26], ["pocas", 85.44, 85.76], ["gotas", 85.88, 86.2], ["le", 86.24, 86.3], ["salvaron", 86.38, 86.8], ["la", 86.84, 86.92], ["vida!", 86.98, 87.32]]}, {"text": "Cuando por fin lo encontraron, estaba muy débil, pero vivo.", "start": 87.6, "end": 91.1, "words": [["Cuando", 87.6, 87.84], ["por", 87.88, 88.06], ["fin", 88.1, 88.24], ["lo", 88.26, 88.32], ["encontraron,", 88.34, 88.98], ["estaba", 89.2, 89.58], ["muy", 89.7, 89.86], ["débil,", 89.94, 90.3], ["pero", 90.6, 90.8], ["vivo.", 90.82, 91.1]]}]}, {"start": 91.42, "end": 97.52, "text": "Su caso es tan extremo que se considera uno de los récords de supervivencia más impresionantes que existen.", "sentences": [{"text": "Su caso es tan extremo que se considera uno de los récords de supervivencia más impresionantes que existen.", "start": 91.42, "end": 97.52, "words": [["Su", 91.42, 91.48], ["caso", 91.58, 91.8], ["es", 91.82, 91.94], ["tan", 92.1, 92.26], ["extremo", 92.32, 92.82], ["que", 92.96, 93.02], ["se", 93.06, 93.16], ["considera", 93.18, 93.66], ["uno", 93.72, 93.84], ["de", 93.88, 93.94], ["los", 93.96, 94.1], ["récords", 94.24, 94.62], ["de", 94.64, 94.7], ["supervivencia", 94.76, 95.5], ["más", 95.7, 95.9], ["impresionantes", 95.96, 96.84], ["que", 96.88, 96.94], ["existen.", 96.96, 97.52]]}]}, {"start": 97.8, "end": 112.94, "text": "Por cierto... ¿y los camellos? Mucha gente cree que guardan agua en la joroba. ¡Pero es falso! La joroba es grasa. Su verdadero truco es otro: pueden tomar más de cien litros de agua en solo unos minutos... y sus cuerpos están hechos para perder muy poca.", "sentences": [{"text": "Por cierto...", "start": 97.8, "end": 98.3, "words": [["Por", 97.8, 97.9], ["cierto...", 97.96, 98.3]]}, {"text": "¿y los camellos?", "start": 98.64, "end": 99.62, "words": [["¿y", 98.64, 98.9], ["los", 98.94, 99.08], ["camellos?", 99.14, 99.62]]}, {"text": "Mucha gente cree que guardan agua en la joroba.", "start": 99.98, "end": 102.1, "words": [["Mucha", 99.98, 100.18], ["gente", 100.26, 100.48], ["cree", 100.58, 100.76], ["que", 100.84, 100.94], ["guardan", 100.98, 101.32], ["agua", 101.4, 101.54], ["en", 101.56, 101.6], ["la", 101.64, 101.68], ["joroba.", 101.76, 102.1]]}, {"text": "¡Pero es falso!", "start": 102.32, "end": 103.34, "words": [["¡Pero", 102.32, 102.56], ["es", 102.62, 102.72], ["falso!", 102.88, 103.34]]}, {"text": "La joroba es grasa.", "start": 103.62, "end": 104.7, "words": [["La", 103.62, 103.68], ["joroba", 103.74, 104.06], ["es", 104.1, 104.18], ["grasa.", 104.26, 104.7]]}, {"text": "Su verdadero truco es otro: pueden tomar más de cien litros de agua en solo unos minutos...", "start": 105.0, "end": 110.16, "words": [["Su", 105.0, 105.1], ["verdadero", 105.14, 105.56], ["truco", 105.68, 106.0], ["es", 106.04, 106.16], ["otro:", 106.26, 106.48], ["pueden", 106.72, 106.98], ["tomar", 107.02, 107.32], ["más", 107.36, 107.54], ["de", 107.58, 107.74], ["cien", 107.84, 108.12], ["litros", 108.16, 108.52], ["de", 108.54, 108.62], ["agua", 108.72, 108.9], ["en", 108.94, 109.0], ["solo", 109.14, 109.38], ["unos", 109.44, 109.64], ["minutos...", 109.68, 110.16]]}, {"text": "y sus cuerpos están hechos para perder muy poca.", "start": 110.38, "end": 112.94, "words": [["y", 110.38, 110.42], ["sus", 110.46, 110.64], ["cuerpos", 110.66, 111.04], ["están", 111.1, 111.32], ["hechos", 111.38, 111.64], ["para", 111.68, 111.86], ["perder", 111.9, 112.2], ["muy", 112.38, 112.52], ["poca.", 112.64, 112.94]]}]}]}, {"audio": "guiones/002-sin-agua/alineacion/parte4.json", "duration": 49.3, "paragraphs": [{"start": 0.12, "end": 5.44, "text": "Ahora, una duda muy común: si te pierdes en el mar... ¿puedes tomar agua del mar?", "sentences": [{"text": "Ahora, una duda muy común: si te pierdes en el mar...", "start": 0.12, "end": 3.58, "words": [["Ahora,", 0.12, 0.44], ["una", 0.78, 0.9], ["duda", 0.94, 1.16], ["muy", 1.36, 1.52], ["común:", 1.62, 1.96], ["si", 2.32, 2.38], ["te", 2.44, 2.58], ["pierdes", 2.6, 2.94], ["en", 3.0, 3.08], ["el", 3.1, 3.24], ["mar...", 3.3, 3.58]]}, {"text": "¿puedes tomar agua del mar?", "start": 3.94, "end": 5.44, "words": [["¿puedes", 3.94, 4.28], ["tomar", 4.34, 4.64], ["agua", 4.72, 4.9], ["del", 4.96, 5.08], ["mar?", 5.2, 5.44]]}]}, {"start": 5.88, "end": 16.9, "text": "La respuesta es NO. El agua de mar tiene tanta sal que, para eliminarla, tus riñones necesitan gastar más agua de la que estás tomando. ¡Te deshidratas todavía más rápido!", "sentences": [{"text": "La respuesta es NO.", "start": 5.88, "end": 7.44, "words": [["La", 5.88, 5.96], ["respuesta", 6.02, 6.6], ["es", 6.8, 7.0], ["NO.", 7.24, 7.44]]}, {"text": "El agua de mar tiene tanta sal que, para eliminarla, tus riñones necesitan gastar más agua de la que estás tomando.", "start": 7.9, "end": 14.54, "words": [["El", 7.9, 7.98], ["agua", 8.02, 8.18], ["de", 8.22, 8.32], ["mar", 8.38, 8.52], ["tiene", 8.6, 8.8], ["tanta", 9.0, 9.32], ["sal", 9.48, 9.72], ["que,", 9.88, 10.0], ["para", 10.14, 10.24], ["eliminarla,", 10.28, 10.88], ["tus", 11.08, 11.24], ["riñones", 11.3, 11.72], ["necesitan", 11.76, 12.26], ["gastar", 12.3, 12.62], ["más", 12.8, 13.06], ["agua", 13.16, 13.36], ["de", 13.4, 13.46], ["la", 13.5, 13.56], ["que", 13.62, 13.68], ["estás", 13.72, 14.02], ["tomando.", 14.08, 14.54]]}, {"text": "¡Te deshidratas todavía más rápido!", "start": 14.74, "end": 16.9, "words": [["¡Te", 14.74, 14.84], ["deshidratas", 14.88, 15.46], ["todavía", 15.5, 15.98], ["más", 16.1, 16.34], ["rápido!", 16.44, 16.9]]}]}, {"start": 16.94, "end": 39.08, "text": "¿Y qué hacer si algún día te quedas sin agua? Hay tres reglas de supervivencia. Primero: busca sombra, porque el sol te hace sudar muchísimo más. Segundo: muévete lo menos posible, o hazlo de noche, cuando hace fresco. Y tercero, algo que pocos saben: si no tienes agua, come lo menos posible... porque digerir la comida también gasta agua.", "sentences": [{"text": "¿Y qué hacer si algún día te quedas sin agua?", "start": 16.94, "end": 19.48, "words": [["¿Y", 16.94, 17.4], ["qué", 17.54, 17.6], ["hacer", 17.64, 17.86], ["si", 17.94, 18.0], ["algún", 18.04, 18.28], ["día", 18.36, 18.52], ["te", 18.6, 18.68], ["quedas", 18.72, 18.96], ["sin", 19.0, 19.14], ["agua?", 19.22, 19.48]]}, {"text": "Hay tres reglas de supervivencia.", "start": 19.78, "end": 21.7, "words": [["Hay", 19.78, 19.92], ["tres", 20.1, 20.32], ["reglas", 20.48, 20.76], ["de", 20.8, 20.84], ["supervivencia.", 20.92, 21.7]]}, {"text": "Primero: busca sombra, porque el sol te hace sudar muchísimo más.", "start": 21.96, "end": 26.04, "words": [["Primero:", 21.96, 22.32], ["busca", 22.68, 22.94], ["sombra,", 23.08, 23.44], ["porque", 23.64, 23.84], ["el", 23.88, 23.98], ["sol", 24.04, 24.2], ["te", 24.26, 24.34], ["hace", 24.36, 24.54], ["sudar", 24.6, 24.9], ["muchísimo", 25.0, 25.72], ["más.", 25.78, 26.04]]}, {"text": "Segundo: muévete lo menos posible, o hazlo de noche, cuando hace fresco.", "start": 26.4, "end": 30.82, "words": [["Segundo:", 26.4, 26.84], ["muévete", 27.18, 27.58], ["lo", 27.62, 27.74], ["menos", 27.82, 28.14], ["posible,", 28.18, 28.66], ["o", 28.92, 28.98], ["hazlo", 29.06, 29.28], ["de", 29.32, 29.4], ["noche,", 29.46, 29.76], ["cuando", 29.96, 30.14], ["hace", 30.18, 30.4], ["fresco.", 30.44, 30.82]]}, {"text": "Y tercero, algo que pocos saben: si no tienes agua, come lo menos posible...", "start": 31.1, "end": 36.3, "words": [["Y", 31.1, 31.14], ["tercero,", 31.22, 31.68], ["algo", 32.02, 32.26], ["que", 32.28, 32.5], ["pocos", 32.56, 32.88], ["saben:", 32.94, 33.3], ["si", 33.56, 33.66], ["no", 33.72, 33.78], ["tienes", 33.86, 34.12], ["agua,", 34.24, 34.48], ["come", 34.76, 35.02], ["lo", 35.08, 35.16], ["menos", 35.36, 35.74], ["posible...", 35.78, 36.3]]}, {"text": "porque digerir la comida también gasta agua.", "start": 36.5, "end": 39.08, "words": [["porque", 36.5, 36.72], ["digerir", 36.76, 37.14], ["la", 37.18, 37.28], ["comida", 37.32, 37.68], ["también", 37.84, 38.32], ["gasta", 38.4, 38.74], ["agua.", 38.82, 39.08]]}]}, {"start": 39.42, "end": 49.0, "text": "Y si encuentras agua de un río o de un charco, lo ideal es hervirla. Puede tener bacterias que te causen diarrea... y la diarrea te deshidrata todavía más rápido.", "sentences": [{"text": "Y si encuentras agua de un río o de un charco, lo ideal es hervirla.", "start": 39.42, "end": 43.32, "words": [["Y", 39.42, 39.46], ["si", 39.5, 39.54], ["encuentras", 39.58, 40.02], ["agua", 40.1, 40.26], ["de", 40.3, 40.36], ["un", 40.4, 40.5], ["río", 40.58, 40.92], ["o", 40.98, 41.02], ["de", 41.06, 41.14], ["un", 41.18, 41.28], ["charco,", 41.3, 41.68], ["lo", 41.92, 42.02], ["ideal", 42.06, 42.5], ["es", 42.58, 42.7], ["hervirla.", 42.72, 43.32]]}, {"text": "Puede tener bacterias que te causen diarrea...", "start": 43.58, "end": 45.72, "words": [["Puede", 43.58, 43.8], ["tener", 43.84, 44.06], ["bacterias", 44.1, 44.6], ["que", 44.62, 44.7], ["te", 44.74, 44.84], ["causen", 44.88, 45.2], ["diarrea...", 45.24, 45.72]]}, {"text": "y la diarrea te deshidrata todavía más rápido.", "start": 45.94, "end": 49.0, "words": [["y", 45.94, 45.98], ["la", 46.02, 46.1], ["diarrea", 46.14, 46.6], ["te", 46.66, 46.74], ["deshidrata", 46.78, 47.42], ["todavía", 47.46, 48.12], ["más", 48.26, 48.5], ["rápido.", 48.58, 49.0]]}]}]}, {"audio": "guiones/002-sin-agua/alineacion/parte5.json", "duration": 104.38, "paragraphs": [{"start": 0.08, "end": 5.8, "text": "Y aquí viene la sorpresa que te prometí: tomar DEMASIADA agua también es peligroso.", "sentences": [{"text": "Y aquí viene la sorpresa que te prometí: tomar DEMASIADA agua también es peligroso.", "start": 0.08, "end": 5.8, "words": [["Y", 0.08, 0.14], ["aquí", 0.2, 0.48], ["viene", 0.52, 0.76], ["la", 0.8, 0.86], ["sorpresa", 0.94, 1.46], ["que", 1.48, 1.56], ["te", 1.6, 1.7], ["prometí:", 1.72, 2.2], ["tomar", 2.64, 2.92], ["DEMASIADA", 3.0, 3.84], ["agua", 3.98, 4.28], ["también", 4.48, 5.02], ["es", 5.06, 5.18], ["peligroso.", 5.2, 5.8]]}]}, {"start": 6.12, "end": 22.42, "text": "Si tomas muchísima agua en muy poco tiempo, la sal de tu sangre se diluye demasiado. Tus células se hinchan como globos... incluso las del cerebro. Se llama intoxicación por agua, y ha pasado en concursos y retos donde la gente bebe litros y litros sin parar.", "sentences": [{"text": "Si tomas muchísima agua en muy poco tiempo, la sal de tu sangre se diluye demasiado.", "start": 6.12, "end": 11.26, "words": [["Si", 6.12, 6.2], ["tomas", 6.26, 6.58], ["muchísima", 6.64, 7.4], ["agua", 7.5, 7.68], ["en", 7.72, 7.88], ["muy", 7.92, 8.04], ["poco", 8.14, 8.32], ["tiempo,", 8.4, 8.76], ["la", 8.98, 9.04], ["sal", 9.14, 9.26], ["de", 9.3, 9.36], ["tu", 9.42, 9.48], ["sangre", 9.58, 9.88], ["se", 9.96, 10.06], ["diluye", 10.08, 10.48], ["demasiado.", 10.52, 11.26]]}, {"text": "Tus células se hinchan como globos...", "start": 11.5, "end": 13.38, "words": [["Tus", 11.5, 11.62], ["células", 11.66, 12.04], ["se", 12.1, 12.22], ["hinchan", 12.24, 12.56], ["como", 12.64, 12.82], ["globos...", 12.88, 13.38]]}, {"text": "incluso las del cerebro.", "start": 13.68, "end": 15.26, "words": [["incluso", 13.68, 14.32], ["las", 14.42, 14.56], ["del", 14.6, 14.72], ["cerebro.", 14.8, 15.26]]}, {"text": "Se llama intoxicación por agua, y ha pasado en concursos y retos donde la gente bebe litros y litros sin parar.", "start": 15.6, "end": 22.42, "words": [["Se", 15.6, 15.68], ["llama", 15.74, 16.14], ["intoxicación", 16.2, 17.2], ["por", 17.24, 17.36], ["agua,", 17.46, 17.7], ["y", 17.92, 17.96], ["ha", 18.0, 18.02], ["pasado", 18.1, 18.4], ["en", 18.42, 18.52], ["concursos", 18.56, 19.14], ["y", 19.18, 19.22], ["retos", 19.32, 19.68], ["donde", 19.74, 19.92], ["la", 19.96, 20.0], ["gente", 20.08, 20.36], ["bebe", 20.4, 20.64], ["litros", 20.78, 21.24], ["y", 21.3, 21.34], ["litros", 21.46, 21.82], ["sin", 21.86, 21.98], ["parar.", 22.08, 22.42]]}]}, {"start": 22.8, "end": 37.92, "text": "Entonces, ¿cuánta agua necesitas de verdad? Las autoridades de salud europeas recomiendan alrededor de dos litros al día para las mujeres, y dos y medio para los hombres... ¡pero contando el agua de la comida! La fruta, la sopa y hasta el pan tienen agua.", "sentences": [{"text": "Entonces, ¿cuánta agua necesitas de verdad?", "start": 22.8, "end": 25.36, "words": [["Entonces,", 22.8, 23.38], ["¿cuánta", 23.62, 24.0], ["agua", 24.08, 24.24], ["necesitas", 24.28, 24.86], ["de", 24.9, 24.96], ["verdad?", 25.02, 25.36]]}, {"text": "Las autoridades de salud europeas recomiendan alrededor de dos litros al día para las mujeres, y dos y medio para los hombres...", "start": 25.72, "end": 32.64, "words": [["Las", 25.72, 25.82], ["autoridades", 25.86, 26.42], ["de", 26.46, 26.52], ["salud", 26.58, 26.82], ["europeas", 26.88, 27.48], ["recomiendan", 27.62, 28.12], ["alrededor", 28.18, 28.68], ["de", 28.74, 28.82], ["dos", 28.96, 29.14], ["litros", 29.24, 29.56], ["al", 29.6, 29.68], ["día", 29.76, 29.98], ["para", 30.0, 30.14], ["las", 30.18, 30.28], ["mujeres,", 30.36, 30.84], ["y", 31.02, 31.08], ["dos", 31.2, 31.38], ["y", 31.42, 31.46], ["medio", 31.56, 31.84], ["para", 31.86, 32.0], ["los", 32.04, 32.18], ["hombres...", 32.22, 32.64]]}, {"text": "¡pero contando el agua de la comida!", "start": 32.84, "end": 34.6, "words": [["¡pero", 32.84, 33.1], ["contando", 33.14, 33.58], ["el", 33.62, 33.7], ["agua", 33.76, 33.94], ["de", 33.98, 34.04], ["la", 34.08, 34.12], ["comida!", 34.2, 34.6]]}, {"text": "La fruta, la sopa y hasta el pan tienen agua.", "start": 34.92, "end": 37.92, "words": [["La", 34.92, 35.0], ["fruta,", 35.12, 35.62], ["la", 35.74, 35.8], ["sopa", 35.96, 36.4], ["y", 36.44, 36.5], ["hasta", 36.54, 36.76], ["el", 36.8, 36.86], ["pan", 37.04, 37.24], ["tienen", 37.32, 37.58], ["agua.", 37.68, 37.92]]}]}, {"start": 38.18, "end": 45.98, "text": "Y el mejor truco es simple: toma agua de forma regular durante el día, y fíjate en el color de tu orina. Si es amarillo clarito, vas bien.", "sentences": [{"text": "Y el mejor truco es simple: toma agua de forma regular durante el día, y fíjate en el color de tu orina.", "start": 38.18, "end": 43.88, "words": [["Y", 38.18, 38.22], ["el", 38.26, 38.32], ["mejor", 38.36, 38.58], ["truco", 38.68, 38.98], ["es", 39.04, 39.14], ["simple:", 39.18, 39.54], ["toma", 39.84, 40.08], ["agua", 40.16, 40.36], ["de", 40.4, 40.5], ["forma", 40.56, 40.76], ["regular", 40.84, 41.24], ["durante", 41.3, 41.6], ["el", 41.62, 41.7], ["día,", 41.76, 42.0], ["y", 42.22, 42.26], ["fíjate", 42.4, 42.76], ["en", 42.8, 42.86], ["el", 42.9, 43.02], ["color", 43.04, 43.3], ["de", 43.34, 43.42], ["tu", 43.48, 43.54], ["orina.", 43.58, 43.88]]}, {"text": "Si es amarillo clarito, vas bien.", "start": 44.18, "end": 45.98, "words": [["Si", 44.18, 44.24], ["es", 44.28, 44.36], ["amarillo", 44.42, 44.78], ["clarito,", 44.82, 45.26], ["vas", 45.54, 45.72], ["bien.", 45.78, 45.98]]}]}, {"start": 46.3, "end": 58.62, "text": "Y hay señales de alerta que nunca debes ignorar: mareo fuerte, confusión, latidos muy rápidos... o no haber orinado en muchas horas. Si pasa eso, hay que tomar líquidos y buscar ayuda.", "sentences": [{"text": "Y hay señales de alerta que nunca debes ignorar: mareo fuerte, confusión, latidos muy rápidos...", "start": 46.3, "end": 53.1, "words": [["Y", 46.3, 46.34], ["hay", 46.36, 46.46], ["señales", 46.52, 46.88], ["de", 46.92, 46.96], ["alerta", 47.0, 47.34], ["que", 47.46, 47.6], ["nunca", 47.76, 48.14], ["debes", 48.18, 48.46], ["ignorar:", 48.52, 48.94], ["mareo", 49.38, 49.64], ["fuerte,", 49.78, 50.22], ["confusión,", 50.58, 51.26], ["latidos", 51.66, 52.08], ["muy", 52.26, 52.44], ["rápidos...", 52.5, 53.1]]}, {"text": "o no haber orinado en muchas horas.", "start": 53.4, "end": 55.26, "words": [["o", 53.4, 53.44], ["no", 53.54, 53.62], ["haber", 53.66, 53.86], ["orinado", 53.9, 54.32], ["en", 54.36, 54.5], ["muchas", 54.56, 54.9], ["horas.", 54.92, 55.26]]}, {"text": "Si pasa eso, hay que tomar líquidos y buscar ayuda.", "start": 55.58, "end": 58.62, "words": [["Si", 55.58, 55.64], ["pasa", 55.74, 56.02], ["eso,", 56.12, 56.34], ["hay", 56.52, 56.62], ["que", 56.64, 56.74], ["tomar", 56.78, 57.06], ["líquidos", 57.12, 57.68], ["y", 57.72, 57.76], ["buscar", 57.82, 58.2], ["ayuda.", 58.26, 58.62]]}]}, {"start": 58.96, "end": 71.82, "text": "Además, no todos aguantan igual. Los bebés y los adultos mayores se deshidratan mucho más rápido. Los bebés porque su cuerpo es pequeño y pierde agua muy rápido... y los adultos mayores porque muchas veces sienten menos sed.", "sentences": [{"text": "Además, no todos aguantan igual.", "start": 58.96, "end": 60.92, "words": [["Además,", 58.96, 59.4], ["no", 59.62, 59.7], ["todos", 59.84, 60.1], ["aguantan", 60.18, 60.56], ["igual.", 60.6, 60.92]]}, {"text": "Los bebés y los adultos mayores se deshidratan mucho más rápido.", "start": 61.22, "end": 64.66, "words": [["Los", 61.22, 61.34], ["bebés", 61.42, 61.72], ["y", 61.74, 61.78], ["los", 61.82, 61.94], ["adultos", 62.0, 62.36], ["mayores", 62.4, 62.84], ["se", 62.88, 62.94], ["deshidratan", 62.98, 63.56], ["mucho", 63.68, 63.94], ["más", 64.02, 64.2], ["rápido.", 64.26, 64.66]]}, {"text": "Los bebés porque su cuerpo es pequeño y pierde agua muy rápido...", "start": 64.92, "end": 68.18, "words": [["Los", 64.92, 65.06], ["bebés", 65.1, 65.44], ["porque", 65.48, 65.7], ["su", 65.74, 65.8], ["cuerpo", 65.88, 66.14], ["es", 66.16, 66.26], ["pequeño", 66.3, 66.76], ["y", 66.78, 66.82], ["pierde", 66.92, 67.18], ["agua", 67.26, 67.5], ["muy", 67.54, 67.68], ["rápido...", 67.74, 68.18]]}, {"text": "y los adultos mayores porque muchas veces sienten menos sed.", "start": 68.42, "end": 71.82, "words": [["y", 68.42, 68.44], ["los", 68.48, 68.6], ["adultos", 68.66, 69.0], ["mayores", 69.06, 69.56], ["porque", 69.6, 69.9], ["muchas", 69.98, 70.32], ["veces", 70.36, 70.72], ["sienten", 70.78, 71.2], ["menos", 71.26, 71.54], ["sed.", 71.62, 71.82]]}]}, {"start": 72.12, "end": 82.34, "text": "¿Y el café o el refresco cuentan? El café y el té también hidratan, aunque tengan cafeína. Pero los refrescos tienen mucha azúcar... así que el agua sigue siendo la campeona.", "sentences": [{"text": "¿Y el café o el refresco cuentan?", "start": 72.12, "end": 73.9, "words": [["¿Y", 72.12, 72.2], ["el", 72.24, 72.3], ["café", 72.38, 72.74], ["o", 72.78, 72.82], ["el", 72.88, 72.94], ["refresco", 73.0, 73.44], ["cuentan?", 73.54, 73.9]]}, {"text": "El café y el té también hidratan, aunque tengan cafeína.", "start": 74.24, "end": 77.28, "words": [["El", 74.24, 74.32], ["café", 74.36, 74.64], ["y", 74.68, 74.72], ["el", 74.76, 74.84], ["té", 74.94, 75.08], ["también", 75.18, 75.52], ["hidratan,", 75.54, 76.0], ["aunque", 76.22, 76.46], ["tengan", 76.5, 76.76], ["cafeína.", 76.8, 77.28]]}, {"text": "Pero los refrescos tienen mucha azúcar...", "start": 77.56, "end": 79.9, "words": [["Pero", 77.56, 77.72], ["los", 77.74, 77.88], ["refrescos", 77.94, 78.58], ["tienen", 78.62, 78.92], ["mucha", 79.06, 79.38], ["azúcar...", 79.44, 79.9]]}, {"text": "así que el agua sigue siendo la campeona.", "start": 80.22, "end": 82.34, "words": [["así", 80.22, 80.4], ["que", 80.48, 80.54], ["el", 80.58, 80.66], ["agua", 80.76, 80.98], ["sigue", 81.14, 81.42], ["siendo", 81.46, 81.7], ["la", 81.74, 81.8], ["campeona.", 81.86, 82.34]]}]}, {"start": 82.66, "end": 90.6, "text": "Tu cuerpo es una máquina increíble, pero necesita agua para funcionar. Sin ella, en solo unos días, todo empieza a apagarse.", "sentences": [{"text": "Tu cuerpo es una máquina increíble, pero necesita agua para funcionar.", "start": 82.66, "end": 86.74, "words": [["Tu", 82.66, 82.72], ["cuerpo", 82.82, 83.1], ["es", 83.12, 83.22], ["una", 83.26, 83.4], ["máquina", 83.52, 83.92], ["increíble,", 83.96, 84.68], ["pero", 84.92, 85.06], ["necesita", 85.1, 85.66], ["agua", 85.76, 85.98], ["para", 86.02, 86.18], ["funcionar.", 86.22, 86.74]]}, {"text": "Sin ella, en solo unos días, todo empieza a apagarse.", "start": 87.06, "end": 90.6, "words": [["Sin", 87.06, 87.22], ["ella,", 87.3, 87.52], ["en", 87.8, 87.86], ["solo", 87.98, 88.22], ["unos", 88.26, 88.52], ["días,", 88.54, 88.94], ["todo", 89.24, 89.44], ["empieza", 89.48, 89.94], ["a", 89.94, 89.96], ["apagarse.", 89.98, 90.6]]}]}, {"start": 90.9, "end": 96.62, "text": "Y ahora te pregunto a ti: ¿cuál es el máximo tiempo que has estado sin tomar agua? ¡Cuéntamelo en los comentarios!", "sentences": [{"text": "Y ahora te pregunto a ti: ¿cuál es el máximo tiempo que has estado sin tomar agua?", "start": 90.9, "end": 95.08, "words": [["Y", 90.9, 90.94], ["ahora", 90.98, 91.18], ["te", 91.24, 91.34], ["pregunto", 91.38, 91.72], ["a", 91.76, 91.78], ["ti:", 91.86, 92.0], ["¿cuál", 92.26, 92.42], ["es", 92.46, 92.56], ["el", 92.62, 92.7], ["máximo", 92.84, 93.28], ["tiempo", 93.38, 93.68], ["que", 93.76, 93.82], ["has", 93.84, 93.92], ["estado", 93.98, 94.32], ["sin", 94.38, 94.48], ["tomar", 94.54, 94.78], ["agua?", 94.86, 95.08]]}, {"text": "¡Cuéntamelo en los comentarios!", "start": 95.3, "end": 96.62, "words": [["¡Cuéntamelo", 95.3, 95.76], ["en", 95.78, 95.82], ["los", 95.86, 95.96], ["comentarios!", 96.0, 96.62]]}]}, {"start": 96.92, "end": 104.08, "text": "Y si te preguntas qué pasa si dejas de COMER... la respuesta te va a sorprender. ¡Te lo cuento en el próximo video!", "sentences": [{"text": "Y si te preguntas qué pasa si dejas de COMER...", "start": 96.92, "end": 99.78, "words": [["Y", 96.92, 96.96], ["si", 97.02, 97.08], ["te", 97.14, 97.24], ["preguntas", 97.26, 97.82], ["qué", 98.02, 98.24], ["pasa", 98.3, 98.54], ["si", 98.64, 98.76], ["dejas", 98.8, 99.14], ["de", 99.18, 99.3], ["COMER...", 99.34, 99.78]]}, {"text": "la respuesta te va a sorprender.", "start": 100.18, "end": 102.18, "words": [["la", 100.18, 100.24], ["respuesta", 100.34, 101.0], ["te", 101.14, 101.28], ["va", 101.34, 101.42], ["a", 101.46, 101.48], ["sorprender.", 101.56, 102.18]]}, {"text": "¡Te lo cuento en el próximo video!", "start": 102.46, "end": 104.08, "words": [["¡Te", 102.46, 102.54], ["lo", 102.58, 102.64], ["cuento", 102.74, 103.0], ["en", 103.04, 103.1], ["el", 103.14, 103.2], ["próximo", 103.32, 103.72], ["video!", 103.76, 104.08]]}]}]}];
